 function readStored(key){try{const value=JSON.parse(localStorage.getItem(key)||'null');return value&&Array.isArray(value.marks)?value:null;}catch{return null;}}
 function defaultGoals(){return $('rinkSvg').dataset.goalTemplate==='movable'?[{id:uuid(),type:'goal',x:240,y:78,color:'#b11226',angle:0},{id:uuid(),type:'goal',x:240,y:786,color:'#b11226',angle:180}]:[];}
 function applyRecord(value){
  marks=safeMarks(value.marks);if(!value.goalsVersion&&!marks.some(m=>m.type==='goal'))marks.push(...defaultGoals());history=[];future=[];selectedId=null;
  $('rinkTitle').value=String(value.title||'').slice(0,100);$('rinkDescription').value=String(value.description||'').slice(0,2000);
  const aliases={'Skridskoteknik':'Skridskoåkning','Passningar':'Passningar och mottagningar','Skott':'Skott och avslut','Målvakter':'Målvaktsträning','Spelsituationer':'Spelförståelse'},categories=(value.categories||[value.category]).map(c=>aliases[c]||c);
  for(const option of $('rinkCategory').options)option.selected=categories.includes(option.value);
  if(!$('rinkCategory').selectedOptions&&categories.length===1)$('rinkCategory').value=categories[0];
  for(const check of document.querySelectorAll('[data-rink-category]'))check.checked=categories.includes(check.value);
  $('rinkSettingsSummary').textContent=$('rinkTitle').value.trim()||'Övningens uppgifter';render();
 }
 function restore(){const draft=readStored(DRAFT),saved=draft||readStored(SAVED);if(saved){applyRecord(saved);$('rinkDraftStatus').textContent=draft?'Utkast återställt från denna enhet.':'Senaste sparade övningen öppnad.';}else{marks=defaultGoals();render();}}
 function drawFromText(){
  const text=$('rinkDescription').value.trim();if(!text){announce('Beskriv först övningen.');return;}
  const parser=window.NskRinkTextParser;if(!parser){announce('Texttolkningen kunde inte laddas. Uppdatera sidan.');return;}
  const result=parser.parse(text,$('rinkColor').value,{goals:marks.filter(m=>m.type==='goal')});if(!result.marks.length){announce('Ingen ritning skapades. Prova: 2 röda spelare vid nedre vänstra hörnet.');return;}
  if(marks.some(m=>m.type!=='goal')&&!confirm('Ersätt ritningen med övningen från beskrivningen?'))return;
  remember();if(!result.marks.some(m=>m.type==='goal'))result.marks.unshift(...marks.filter(m=>m.type==='goal'));marks=safeMarks(result.marks.map(m=>({...m,id:uuid()})));selectedId=null;render();saveDraft();$('rinkSettings').open=false;$('rinkSettings').hidden=true;
  announce(marks.length+' objekt ritade.'+(result.warnings.length?' Förtydliga: '+result.warnings.slice(0,2).join(' / '):''));
 }
 function archiveDrawing(record){
  return new Promise((resolve,reject)=>{
   const request=indexedDB.open('nsk_exercise_files_v1',1);
   request.onupgradeneeded=()=>{
    if(!request.result.objectStoreNames.contains('files'))request.result.createObjectStore('files',{keyPath:'id'});
   };
   request.onerror=()=>reject(request.error);
   request.onsuccess=()=>{
    const db=request.result;
    const tx=db.transaction('files','readwrite');
    tx.objectStore('files').put(record);
    tx.oncomplete=()=>{db.close();resolve();};
    tx.onerror=()=>{db.close();reject(tx.error);};
    tx.onabort=()=>{db.close();reject(tx.error);};
   };
  });
 }
 function showDrawingSettings(){if(fullscreenOn)setRinkFullscreen(false);closeMenus();$('rinkSettings').hidden=false;$('rinkSettings').open=true;}
 async function saveDrawing(){
  if(!marks.length){announce('Rita först symboler och rörelser på rinken.');return;}
  const title=$('rinkTitle').value.trim(),category=selectedCategories().join(', ');
  if(!title||!category){showDrawingSettings();announce(!title?'Ge övningen ett namn innan du sparar.':'Välj kategori innan du sparar.');(!title?$('rinkTitle'):(document.querySelectorAll('[data-rink-category]')[0]||$('rinkCategory'))).focus();return;}
  const button=$('rinkSave');button.disabled=true;closeMenus();
  try{
   const saved={...record(),title};
   localStorage.setItem(SAVED,JSON.stringify(saved));flushDraft();
   const blob=new Blob([new XMLSerializer().serializeToString(cleanSvg())],{type:'image/svg+xml'});
   await archiveDrawing({id:uuid(),origin:'rink-drawer',title:saved.title,description:saved.description,category:saved.category,categories:saved.categories,filename:'hockeyovning.svg',blob,created:Date.now()});
   announce('Sparad i Övningsarkivet på denna enhet.');
  }catch(error){announce('Kunde inte spara i Övningsarkivet: '+(error.message||'okänt fel'));}
  finally{button.disabled=false;}
 }
 function exportImage(){
  closeMenus();const blob=new Blob([new XMLSerializer().serializeToString(cleanSvg())],{type:'image/svg+xml;charset=utf-8'});
  const url=URL.createObjectURL(blob),img=new Image();
  img.onload=()=>{const canvas=document.createElement('canvas');canvas.width=960;canvas.height=1720;canvas.getContext('2d').drawImage(img,0,0,canvas.width,canvas.height);URL.revokeObjectURL(url);canvas.toBlob(png=>{
   if(!png){announce('Kunde inte skapa PNG.');return;}const href=URL.createObjectURL(png),a=document.createElement('a');a.href=href;a.download=($('rinkTitle').value.trim()||'nsk-hockeyovning').replace(/[^a-z0-9åäö _-]/gi,'')+'.png';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(href),30000);announce('Bilden exporterades.');
  },'image/png');};img.onerror=()=>{URL.revokeObjectURL(url);announce('Bilden kunde inte exporteras.');};img.src=url;
 }
